func TestCreateBackup_SameParentDirectory(t *testing.T) {
	tmpDir := t.TempDir()

	// Create source directory
	srcDir := filepath.Join(tmpDir, ".ai-rulez")
	err := os.MkdirAll(srcDir, 0o755)
