        card = client.create_card(name="Test", query="SELECT 1", display="scalar")
        assert card["id"] == 42

        body = responses.calls[0].request.body
        assert b'"name": "Test"' in body
        assert b'"type": "native"' in body
        assert b'"display": "scalar"' in body

