func TestResolve(t *testing.T) {
	tests := []struct {
		name string
		input string
		want string
	}{
		{"basic", ""test"", ""result""},
		{"empty", "", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := resolve(tt.input)
			if got != tt.want {
				t.Errorf("resolve() = %v, want %v", got, tt.want)
			}
		})
	}
}

