"""Tests for MetabaseClient HTTP layer and initialization."""

import pytest
import requests
import responses

from metabase_toolkit import MetabaseClient, MetabaseConfig, MetabaseError

from .conftest import API_KEY, API_URL, BASE_URL, SAMPLE_USER


class TestClientInit:
    def test_from_config(self):
        config = MetabaseConfig(site_url=BASE_URL, api_key=API_KEY)
        client = MetabaseClient(config=config)
        assert client.config.site_url == BASE_URL
        assert client.headers["x-api-key"] == API_KEY

    def test_from_kwargs(self, monkeypatch):
        monkeypatch.delenv("METABASE_URL", raising=False)
        monkeypatch.delenv("METABASE_API_KEY", raising=False)
        client = MetabaseClient(site_url=BASE_URL, api_key=API_KEY)
        assert client.config.site_url == BASE_URL

    def test_from_env(self, monkeypatch):
        monkeypatch.setenv("METABASE_URL", BASE_URL)
        monkeypatch.setenv("METABASE_API_KEY", API_KEY)
        client = MetabaseClient()
        assert client.config.site_url == BASE_URL

    def test_headers_include_api_key(self, client):
        assert client.headers["x-api-key"] == API_KEY
        assert client.headers["Content-Type"] == "application/json"


class TestHttpErrors:
    @responses.activate
    def test_404_raises_metabase_error(self, client):
        responses.add(
            responses.GET,
            f"{API_URL}/card/999",
            json={"message": "Not found"},
            status=404,
        )
        with pytest.raises(MetabaseError) as exc_info:
            client.get_card(999)
        assert exc_info.value.status_code == 404
        assert "Not found" in str(exc_info.value)

    @responses.activate
    def test_500_raises_metabase_error(self, client):
        responses.add(
            responses.GET,
            f"{API_URL}/card/1",
            json={"error": "Internal server error"},
            status=500,
        )
        with pytest.raises(MetabaseError) as exc_info:
            client.get_card(1)
        assert exc_info.value.status_code == 500

    @responses.activate
    def test_connection_error(self, client):
        responses.add(
            responses.GET,
            f"{API_URL}/user/current",
            body=requests.ConnectionError("Connection refused"),
        )
        with pytest.raises(MetabaseError, match="Connection failed"):
            client.get_current_user()

    @responses.activate
    def test_invalid_json_response(self, client):
        responses.add(
            responses.GET,
            f"{API_URL}/card/1",
            body="not json",
            status=200,
            content_type="text/plain",
        )
        with pytest.raises(MetabaseError, match="Invalid JSON"):
            client.get_card(1)


class TestHealthCheck:
    @responses.activate
    def test_successful_health_check(self, client):
        responses.add(responses.GET, f"{API_URL}/user/current", json=SAMPLE_USER, status=200)
        result = client.health_check()
        assert result["status"] == "ok"
        assert result["user"] == "Test Admin"
        assert result["is_superuser"] is True

    @responses.activate
    def test_failed_health_check(self, client):
        responses.add(
            responses.GET,
            f"{API_URL}/user/current",
            json={"message": "Unauthorized"},
            status=401,
        )
        result = client.health_check()
        assert result["status"] == "error"
        assert "error" in result


