import { describe, expect, it, vi } from 'vitest';

import { writeVoiceMode } from './voiceMode';

describe('voiceMode', () => {
  it('enables both voice gates using minified replacements', () => {
    const file =
      'const x=1;' +
      'function qX_(){return A9("tengu_amber_quartz",!1)}' +
      'if(A9("tengu_sotto_voce",!1))return`# Output efficiency...`';

    const result = writeVoiceMode(file, true);

    expect(result).not.toBeNull();
    expect(result).toContain('function qX_(){return !0;return A9(');
    expect(result).toContain('if(!0)return`# Output efficiency...`');
  });

  it('patches only amber quartz when enableConciseOutput is false', () => {
    const file =
      'const x=1;' +
      'function qX_(){return A9("tengu_amber_quartz",!1)}' +
      'if(A9("tengu_sotto_voce",!1))return`# Output efficiency...`';

    const result = writeVoiceMode(file, false);

    expect(result).not.toBeNull();
    expect(result).toContain('function qX_(){return !0;return A9(');
    expect(result).toContain(
      'if(A9("tengu_sotto_voce",!1))return`# Output efficiency...`'
    );
  });

  it('matches the amber quartz gate in assignment context', () => {
    const file =
      'const gate=function qX_(){return A9("tengu_amber_quartz",!1)}';

    const result = writeVoiceMode(file, false);

    expect(result).toBe(
      'const gate=function qX_(){return !0;return A9("tengu_amber_quartz",!1)}'
    );
  });

  it('returns null when the amber quartz gate is absent', () => {
    const consoleError = vi
      .spyOn(console, 'error')
      .mockImplementation(() => {});

    try {
      expect(writeVoiceMode('const x=1;', false)).toBeNull();
      expect(consoleError).toHaveBeenCalledWith(
        'patch: voiceMode: failed to find tengu_amber_quartz gate'
      );
    } finally {
      consoleError.mockRestore();
    }
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import fs from 'node:fs'
import path from 'node:path'
import os from 'node:os'

let tmpDir: string

beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'agents-test-'))
})

afterEach(() => {
  fs.rmSync(tmpDir, { recursive: true, force: true })
})

describe('agent adapters', () => {
  it('detects Claude Code when .claude/ exists', async () => {
    const { ClaudeAdapter } = await import('../agents/claude.js')
    const adapter = new ClaudeAdapter(tmpDir)
    expect(adapter.detect()).toBe(false)

    fs.mkdirSync(path.join(tmpDir, '.claude'))
    expect(adapter.detect()).toBe(true)
  })

  it('returns correct skill dir for Claude', async () => {
    const { ClaudeAdapter } = await import('../agents/claude.js')
    const adapter = new ClaudeAdapter(tmpDir)
    expect(adapter.skillDir('my-skill')).toBe(path.join(tmpDir, '.claude', 'skills', 'my-skill'))
  })

  it('detects OpenClaw when ~/.openclaw/ exists', async () => {
    const { OpenClawAdapter } = await import('../agents/openclaw.js')
    const fakeHome = path.join(tmpDir, 'fakehome')
    fs.mkdirSync(fakeHome)
    const adapter = new OpenClawAdapter(tmpDir, fakeHome)
    expect(adapter.detect()).toBe(false)

    fs.mkdirSync(path.join(fakeHome, '.openclaw'))
    expect(adapter.detect()).toBe(true)
  })

  it('installs OpenClaw skills to workspace skills/ dir', async () => {
    const { OpenClawAdapter } = await import('../agents/openclaw.js')
    const adapter = new OpenClawAdapter(tmpDir, tmpDir)
    expect(adapter.skillDir('my-skill')).toBe(path.join(tmpDir, 'skills', 'my-skill'))
  })

  it('detectAll returns only detected agents', async () => {
    const { detectAgents } = await import('../agents/index.js')
    fs.mkdirSync(path.join(tmpDir, '.claude'))
    const detected = detectAgents(tmpDir, tmpDir)
    const names = detected.map(a => a.name)
    expect(names).toContain('claude')
    expect(names).not.toContain('cursor')
    expect(names).toContain('universal')
  })
})

